const source = $input.first().json;
const text = (source.message?.text || '').trim();
const match = text.match(/^\/(승인|보류|거절)\s+(\d+)(?:\s+(.+))?$/);
const action = match?.[1] || '';
return [{json:{chat_id:source.message?.chat?.id, decision_id:match ? Number(match[2]) : null, status:action === '승인' ? 'approved' : action === '보류' ? 'deferred' : action === '거절' ? 'rejected' : 'invalid', note:match?.[3] || '', raw_text:text}}];
